const products = [
  { slug: "trail-pack-45", name: "Trail Pack 45L" },
  { slug: "alpine-1p-tent", name: "Alpine 1P Tent" },
  { slug: "camp-kettle-1l", name: "Camp Kettle 1L" },
];
const state = { cart: [], query: "" };
const app = document.querySelector("#app");

function render() {
  const matching = products.filter((p) => p.name.toLowerCase().includes(state.query.toLowerCase()));
  app.innerHTML = `
    <p>Cart: ${state.cart.length}</p>
    <input name="search" value="${state.query}" placeholder="Search gear">
    <ul>${matching.map((p) => `<li>${p.name} <button data-slug="${p.slug}">Add</button></li>`).join("")}</ul>
  `;
}

app.addEventListener("input", (event) => {
  state.query = event.target.value;
  render();
  console.log("Focus is on:", document.activeElement.tagName);
});

app.addEventListener("click", (event) => {
  const button = event.target.closest("button[data-slug]");
  if (!button) return;
  state.cart.push(button.dataset.slug);
  render();
});

render();

import { Component } from "react";

export class AddToCart extends Component {
  state = { quantity: 0 };

  render() {
    return (
      <button type="button" onClick={() => this.setState({ quantity: this.state.quantity + 1 })}>
        In cart: {this.state.quantity}
      </button>
    );
  }
}

import { formatPrice } from "../lib/format";

type CartItem = { slug: string; name: string; priceCents: number; quantity: number };

const FREE_SHIPPING_CENTS = 5000;

export function CartSummary({ items }: { items: CartItem[] }) {
  const count = items.reduce((sum, item) => sum + item.quantity, 0);
  const totalCents = items.reduce((sum, item) => sum + item.priceCents * item.quantity, 0);
  const remainingCents = FREE_SHIPPING_CENTS - totalCents;

  return (
    <aside>
      <p>Cart: {count}</p>
      <p>Total: {formatPrice(totalCents)}</p>
      {remainingCents > 0 ? (
        <p>Spend {formatPrice(remainingCents)} more for free shipping.</p>
      ) : (
        <p>Your order ships free.</p>
      )}
    </aside>
  );
}
